import useSearchUsers from "../hooks/useSearchUsers";
import { useEffect, useState } from "react";
import { db } from "../js/firebaseConfig";
import { collection, query, onSnapshot } from "firebase/firestore";

export default function Contacts({ currentUser, setChatUser, setChatGroup, setScreen, logout }) {

    // Hook de busca
    const { filtered, search, searchUsers } = useSearchUsers();

    // Estado de grupos
    const [groups, setGroups] = useState([]);

    // Carrega grupos
    useEffect(() => {
        const q = query(collection(db, "groups"));
        const unsub = onSnapshot(q, snap => {
            setGroups(snap.docs.map(d => ({ id: d.id, ...d.data() })));
        });

        return () => unsub();
    }, []);

    // Remove o usuário atual da lista
    const usersToShow = filtered.filter(u => u.id !== currentUser.uid);

    return (
        <div className="whatsapp-container">

            <div className="contacts-header">
                <h2>Conversas</h2>
                <button className="logout-btn" onClick={logout}>Logout</button>
            </div>
            {/* COLUNA ESQUERDA */}
            <div className="sidebar">
                <div className="sidebar-header">Contatos</div>

                <div className="sidebar-search">
                    <input
                        placeholder="Pesquisar"
                        value={search}
                        onChange={e => searchUsers(e.target.value)}
                    />
                </div>

                <h3 style={{ padding: "10px" }}>Usuários</h3>

                {usersToShow.map(u => (
                    <div
                        key={u.id}
                        className="contact-item"
                        onClick={() => {
                            setChatUser(u);
                            setScreen("private");
                        }}
                    >
                        <div className="contact-name">{u.email}</div>
                    </div>
                ))}

                <h3 style={{ padding: "10px" }}>Grupos</h3>

                {groups.map(g => (
                    <div
                        key={g.id}
                        className="contact-item"
                        onClick={() => {
                            setChatGroup(g);
                            setScreen("group");
                        }}
                    >
                        <div className="contact-name">{g.name}</div>
                    </div>
                ))}

                <button onClick={() => setScreen("createGroup")}>
                    Criar grupo
                </button>
            </div>

            {/* DIREITA FICA VAZIA QUANDO NÃO TEM CHAT */}
            <div className="chat-area">
                <div className="chat-header">
                    Selecione uma conversa
                </div>
            </div>

        </div>
    );
}
